here's some update you can add. add these to easily export card images!
use the plugin command:
this will export card ID 1 from the data base
Code:
exportCardImage 1
this will export card ID from 20 to 25
Code:
exportCardImage 20 25
the cards will be saved in the img/cards/ folder. also you need to wait for it to load in game. the first time it runs it will be blank and black images. but after a few seconds it will then be outputted correctly 192 x 288 pixels as png file with filenames 000 to 999. you can edit the finalname format. i run it twice, and for sure on the second try it not black anymore. it takes less than 5 seconds on my end for all my 140 cards to be generated.
this very useful for devs as the current setup of the card sprites are layered.
Spoiler:
Export Card Images
JavaScript:
else if (command === 'exportCardImage') { // x24
            // Check if a range is provided (args[1] will be the end of the range if given)
            var startId = Number(args[0]); // Starting card ID
            var endId = Number(args[1]) || startId; // Ending card ID, defaults to startId if not provided

            var fs = require('fs');
            var path = require('path');

            // Create the folder path if it doesn't exist
            var folderPath = path.join(process.cwd(), 'img/cards');
            if (!fs.existsSync(folderPath)) {
                fs.mkdirSync(folderPath, { recursive: true });
            }

            // Function to export a single card image
            var exportCardImage = function(cardId) {
                if (!cardId || !$dataItems[cardId]) {
                    console.error("Invalid card ID or card not found: " + cardId);
                    return;
                }

                // Set up the card image size (192x288)
                var cardBitmap = new Bitmap(192, 288);

                // Use the actual card sprite rendering
                var card = new Game_Card(cardId);
                var sprite = new Sprite_Card(card);
                sprite.bitmap = cardBitmap;

                // Update sprite logic to render onto the bitmap
                sprite.setFrame(0, 0, 192, 288);
                sprite.update();

                // Save the card image as a PNG
                var fileName = String(cardId).padStart(3, '0') + '.png'; // Pad the filename with zeroes
                var filePath = path.join(folderPath, fileName);

                cardBitmap.addLoadListener(function() {
                    try {
                        var base64Data = cardBitmap._canvas.toDataURL().replace(/^data:image\/png;base64,/, "");
                        fs.writeFileSync(filePath, base64Data, 'base64');
                        console.log("Card image saved at:", filePath);
                    } catch (error) {
                        console.error("Error saving card image:", error);
                    }
                });
            };

            // Loop through the range and export each card image
            for (var cardId = startId; cardId <= endId; cardId++) {
                exportCardImage(cardId);
            }
        }

