};

Game_Card.prototype.type = function() {
    return this.getDynamicNotetagValue('cardType');
};

Game_Card.prototype.element = function() {
    return this.getDynamicNotetagValue('cardElement');
};

Game_Card.prototype.rare = function() {
    return this.getDynamicNotetagValue('cardRare');
};
Game_Card.prototype.unitSkill = function() {
    return this.getDynamicNotetagValue('unitSkill');
};

Game_Card.prototype.partySkill = function() {
    return this.getDynamicNotetagValue('partySkill');
};

Game_Card.prototype.getDynamicNotetagValue = function(tagName) {
    if (this._item && this._item.meta[tagName]) {
        const interpreter = new Game_Interpreter();
        let textValue = interpreter.convertEscapeCharactersTM(this._item.meta[tagName]);
        return parseInt(textValue, 10) || 0;
    }
    return 0;
};

